mapper.select:
SELECT DISTINCT role_permissions.permission_code FROM sys_user_role AS user_roles INNER JOIN sys_role AS roles ON roles.id = user_roles.role_id AND roles.is_enabled = 1 INNER JOIN sys_role_permission AS role_permissions ON role_permissions.role_id = roles.id
WHERE user_roles.user_id = #{userId}
ORDER BY role_permissions.permission_code

SELECT organizations.organization_code FROM sys_user_organization_scope AS scopes INNER JOIN org_organization AS organizations ON organizations.id = scopes.organization_id
WHERE scopes.user_id = #{userId}
ORDER BY organizations.organization_code

mapper.update:

IF EXISTS (SELECT 1 FROM sys_permission WHERE permission_code = #{permissionCode})

    UPDATE sys_permission
    SET permission_name = #{permissionName}
    WHERE permission_code = #{permissionCode};
ELSE

    INSERT INTO sys_permission (
        permission_code,
        permission_name 
    )
    VALUES (#{permissionCode}, #{permissionName});

