INSERT INTO sys_role (
    role_code,        
    role_name,        
    is_enabled,       
    is_system_managed,
    created_by,       
    updated_by        
) VALUES (
    #{roleCode}, #{roleName}, 1, 1, #{actor}, #{actor}
);
SELECT CONVERT(BIGINT, SCOPE_IDENTITY());

INSERT INTO sys_user (
    login_name,              
    display_name,            
    password_hash,           
    primary_organization_id, 
    is_enabled,              
    must_change_password,    
    created_by,              
    updated_by               
) VALUES (
    #{command.loginName}, #{command.displayName}, #{passwordHash}, #{organizationId},
    1, 0, #{actor}, #{actor}
);
SELECT CONVERT(BIGINT, SCOPE_IDENTITY());
